<?php
/** @noinspection PhpUnhandledExceptionInspection */
declare(strict_types=1);

// Test generated by Claude Code.

namespace Tests\Product\Action\Query;

use Module\Product\Action\Dto\ProductDetailsDto;
use Module\Product\Action\Query\GetProductDetailsQry;
use Module\Product\Model\Product;
use Module\Product\Model\ProductQuantity;
use Module\Product\Model\ProductQuantityRepository;
use Module\Product\Model\ProductRepository;
use Module\Shared\Exception\AppNeverException;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Tests\IntegrationTestCase;

class GetProductDetailsQryTest extends IntegrationTestCase
{
    private const int STORE_ID = 10;

    private GetProductDetailsQry $sut;

    private ProductRepository $productRepository;
    private ProductQuantityRepository $quantityRepository;

    public function setUp(): void
    {
        parent::setUp();

        $this->productRepository = $this->container->get(ProductRepository::class);
        $this->quantityRepository = $this->container->get(ProductQuantityRepository::class);

        $this->sut = new GetProductDetailsQry(
            $this->productRepository,
            $this->quantityRepository
        );
        $this->prepareDb();
    }

    #[Test, DataProvider('dataProviderHandle')]
    public function handle(
        int $productId,
        int $storeId,
        string $expectedExceptionClass,
        string $expectedExceptionMessage,
        ?ProductDetailsDto $expected,
    ): void {
        if ($expectedExceptionClass) {
            $this->expectException($expectedExceptionClass);
            $this->expectExceptionMessageMatches('/^' . preg_quote($expectedExceptionMessage, '/') . '$/');
        }

        $result = $this->sut->handle($productId, $storeId);

        $this->assertEquals($expected, $result);
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public static function dataProviderHandle(): array
    {
        return [
            'product not found' => [
                'productId' => 9999,
                'storeId' => self::STORE_ID,
                'expectedExceptionClass' => AppNeverException::class,
                'expectedExceptionMessage' => 'Product not found; productId = 9999',
                'expected' => null,
            ],
            'success - with quantity and imageUrl' => [
                'productId' => 100,
                'storeId' => self::STORE_ID,
                'expectedExceptionClass' => '',
                'expectedExceptionMessage' => '',
                'expected' => new ProductDetailsDto(100, 'ean-1', 'Red square', 'red-square.png', 500),
            ],
            'success - no quantity for store returns null quantity' => [
                'productId' => 100,
                'storeId' => 99,
                'expectedExceptionClass' => '',
                'expectedExceptionMessage' => '',
                'expected' => new ProductDetailsDto(100, 'ean-1', 'Red square', 'red-square.png', null),
            ],
            'success - null imageUrl' => [
                'productId' => 101,
                'storeId' => self::STORE_ID,
                'expectedExceptionClass' => '',
                'expectedExceptionMessage' => '',
                'expected' => new ProductDetailsDto(101, 'ean-2', 'Blue circle', null, 200),
            ],
        ];
    }

    private function prepareDb(): void
    {
        $this->productRepository->saveWithId(Product::factory('ean-1', 'Red square', 'red-square.png', 100));
        $this->productRepository->saveWithId(Product::factory('ean-2', 'Blue circle', null, 101));
        $this->productRepository->flush();

        $this->quantityRepository->saveWithId(ProductQuantity::factory(self::STORE_ID, 100, 500, 1));
        $this->quantityRepository->saveWithId(ProductQuantity::factory(self::STORE_ID, 101, 200, 2));
        $this->quantityRepository->flush();
    }
}
